  const goodReplay = `v1=${computeSignature(SECRET, now, body)}`;
  const before = snapshot();
  const headers: Record<string, string>[] = [
    {},
    { "paygate-signature": signature(body, now, "wrong_secret") },
    { "paygate-signature": original },
    { "paygate-signature": signature(body, now + 7200) },
    // A caller-controlled replay timestamp cannot relax the live signature window.
    { "paygate-signature": original, "x-replay-timestamp": String(now) },
    { "paygate-signature": good, "x-replay-timestamp": String(now) },
    { "paygate-signature": good, "x-replay-timestamp": String(now), "x-replay-signature": `v1=${"0".repeat(64)}` },
